// MmSettlementResult `Settlement` (preview of the pro-rata split of a closed round, plus `settled` = null until it has been settled). The mock also returns `winnerUserId` when the winning bid belongs to a platform account.
type MmSettlementResult struct {
	AuctionId string `json:"auctionId"`
	Lines     []struct {
		AmountIdr int    `json:"amountIdr"`
		Member    string `json:"member"`
		MemberId  string `json:"memberId"`

		// OrgId Marks a business pool member (collective procurement); it gets its own sub-PO.
		OrgId    *string `json:"orgId,omitempty"`
		Quantity float64 `json:"quantity"`
		Share    float64 `json:"share"`
		UserId   *string `json:"userId,omitempty"`
	} `json:"lines"`
	LotQty   float64 `json:"lotQty"`
	PriceIdr int     `json:"priceIdr"`
	Settled  *struct {
		At     time.Time `json:"at"`
		By     string    `json:"by"`
		Trades int       `json:"trades"`
	} `json:"settled"`
	Side   MmSettlementResultSide `json:"side"`
	Title  string                 `json:"title"`
	Unit   string                 `json:"unit"`
	Winner string                 `json:"winner"`

	// WinnerUserId Platform user id of the winning bidder; absent for fictional (bot) bidders.
	WinnerUserId *string `json:"winnerUserId,omitempty"`
}

// MmSettlementResultSide defines model for MmSettlementResult.Side.
type MmSettlementResultSide string

